//! 📊️ Writes declared columns and ordered cells using the actual shared typed value vocabulary.
use crate::standards::v1::subsets::table::schema::snapshot::{SemioTableSnapshot,SemioTableColumn,SemioTableCellKind,SemioTableRow};
use crate::standards::v1::subsets::{base::io::sqlite::snapshot::native_encoding::{self,Writer},value::io::sqlite::snapshot::native_encoding as values};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl,ValueError};
pub(crate) fn encode(snapshot:&SemioTableSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io::IoPayload,ValueError>{native_encoding::encode_admitted(encoding,"semio s.stdio.semio.table.dsl v1\n","s.stdio.semio.table.pack v1",control,|control|crate::standards::v1::subsets::table::io::sqlite::snapshot::admit_values(snapshot,store::sqlite_snapshot::SqliteSnapshotPhase::EncodeNative,control),|writer,encoding|fields(snapshot,writer,encoding))}
fn column(column:&SemioTableColumn,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.delimiter(b"[",encoding)?;writer.string(&column.name,encoding)?;writer.delimiter(b",",encoding)?;writer.byte(if encoding==SnapshotEncoding::Binary{match column.kind{SemioTableCellKind::Null=>0,SemioTableCellKind::Bool=>1,SemioTableCellKind::Int=>2,SemioTableCellKind::Float=>3,SemioTableCellKind::Str=>4,SemioTableCellKind::Bytes=>5}}else{crate::standards::v1::subsets::table::io::text::snapshot::enc_cell_kind(column.kind) as u8})?;writer.delimiter(b"]",encoding)}
fn row(row:&SemioTableRow,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.list(&row.cells,encoding,|writer,value|values::value(value,writer,encoding,0))}
pub(crate) fn fields(snapshot:&SemioTableSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),semio_framework_value::ValueError>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"schema=")?}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\ncolumns=",encoding)?;writer.list(&snapshot.columns,encoding,|writer,value|column(value,writer,encoding))?;writer.delimiter(b"\nrows=",encoding)?;writer.list(&snapshot.rows,encoding,|writer,value|row(value,writer,encoding))}
